from pathlib import Path

index = Path('index.html')
road = Path('ROADMAP.md')
text = index.read_text()

# CSS: compact 52-slot editor + live analysis inside the existing progress modal.
css_anchor = ".progressFooter{display:flex;gap:6px;margin-top:8px}.progressFooter .pixelBtn{flex:1;font-size:7px}"
css_new = css_anchor + ".deckBuilderGroup{border-color:#465a7b}.deckBuilderHead{display:flex;gap:5px;align-items:center;flex-wrap:wrap;margin-bottom:6px}.deckBuilderHead .pixelBtn{font-size:7px;padding:5px 7px}.deckModeState{font-size:7px;color:var(--soft);margin-left:auto}.deckModeState.on{color:var(--cyan);font-weight:900}.deckSlotGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px;margin-top:6px}.deckSlot{min-width:0;border:1px solid #26344a;background:#0c121c;padding:3px}.deckSlot.selected{border-color:#4d8c91;background:#102229;box-shadow:0 0 0 1px #28545b inset}.deckSlotPick,.deckVariantBtn{width:100%;border:1px solid #000;background:#172033;color:var(--text);cursor:pointer;font:inherit}.deckSlotPick{padding:5px 2px;font-size:8px;font-weight:900}.deckSlotPick small{display:block;margin-top:2px;font-size:6px;color:var(--soft);font-weight:400}.deckSlot.selected .deckSlotPick{background:#17343a;color:#bceeed}.deckVariantBtn{margin-top:3px;padding:3px 2px;font-size:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.deckVariantBtn.named{color:#f0d58b;background:#332d1e}.deckVariantBtn:disabled{opacity:.35;cursor:default}.deckAnalysis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px;margin-top:6px}.deckAnalysisBox{padding:5px;border:1px solid #2c3b53;background:#0c131e;font-size:7px;line-height:1.45}.deckAnalysisBox b{color:var(--gold);font-size:9px}.deckRankLine{grid-column:1/-1;display:flex;gap:3px;flex-wrap:wrap}.deckRankChip{padding:2px 4px;border:1px solid #26344a;background:#121b29;font-size:6px}.deckWarn{grid-column:1/-1;padding:5px;border:1px solid #594b2d;background:#201c12;color:#e5ca87;font-size:7px;line-height:1.4}.deckOk{border-color:#2e5948;background:#102219;color:#aee5c2}.jokerPicker{display:flex;gap:4px;flex-wrap:wrap;margin-top:6px}.jokerPicker .pixelBtn{font-size:6px;padding:4px 6px}.deckBuilderNote{font-size:7px;color:var(--soft);line-height:1.45;margin-top:6px}"
assert css_anchor in text, 'progress footer CSS anchor changed'
text = text.replace(css_anchor, css_new, 1)

# HTML: place the deckbuilder after character/theme choices and before unlock lists.
html_anchor = '<div class="themePickerNote">캐릭터는 덱의 행동 경향을, 캐릭터군은 테마 카드의 출현 우선도를 정합니다. 테마를 골라도 일반·다른 카드와 섞이는 오픈형 덱입니다.</div><div class="unlockGroup"><h4>현재 해금 풀</h4>'
html_new = '<div class="themePickerNote">캐릭터는 덱의 행동 경향을, 캐릭터군은 테마 카드의 출현 우선도를 정합니다. 테마를 골라도 일반·다른 카드와 섞이는 오픈형 덱입니다.</div><div class="unlockGroup deckBuilderGroup"><h4>덱 구성 · 52 정규 슬롯</h4><div class="deckBuilderHead"><button id="deckModeBtn" class="pixelBtn" type="button">커스텀 덱 사용</button><button id="deckResetBtn" class="pixelBtn" type="button">추천 29슬롯 복원</button><span id="deckModeState" class="deckModeState">자동 구성</span></div><div id="deckAnalysis" class="deckAnalysis"></div><div id="deckSlotGrid" class="deckSlotGrid"></div><div class="pickerLabel">조커 1장</div><div id="jokerPicker" class="jokerPicker"></div><div class="deckBuilderNote">52개 숫자+무늬 슬롯 중 <b>정확히 29개</b>를 활성화하고 조커 1장을 더해 기존 30장 전투 덱을 구성합니다. 슬롯을 누르면 포함/제외, 아래 변형 버튼을 누르면 그 슬롯의 <b>순수 ↔ 해금 네임드</b>를 순환합니다. 52슬롯 화면은 전투 덱을 52장으로 늘리지 않습니다.</div></div><div class="unlockGroup"><h4>현재 해금 풀</h4>'
assert html_anchor in text, 'progress deckbuilder HTML anchor changed'
text = text.replace(html_anchor, html_new, 1)

# Progress persistence: legacy saves migrate to disabled custom mode with a valid 29-slot seed.
progress_old = "const LEVEL_THRESHOLDS=[0,1,3,6,10];\nfunction defaultProgress(){return{totalClears:0,selectedChar:'wanderer',selectedTheme:'mixed',tutorialPromptSeen:false,tutorialCompleted:false,chars:{wanderer:0,collector:0,salvager:0,jester:0}}}\nfunction normalizeProgress(x){const base=defaultProgress();if(!x||typeof x!=='object')return base;const chars={...base.chars};for(const id of Object.keys(chars)){const n=Number(x.chars?.[id]);if(Number.isFinite(n)&&n>=0)chars[id]=Math.floor(n)}const tc=Number(x.totalClears);return{totalClears:Number.isFinite(tc)&&tc>=0?Math.floor(tc):0,selectedChar:Object.prototype.hasOwnProperty.call(CHARACTERS,x.selectedChar)?x.selectedChar:'wanderer',selectedTheme:Object.prototype.hasOwnProperty.call(THEME_BUILD_PROFILES,x.selectedTheme)?x.selectedTheme:'mixed',tutorialPromptSeen:typeof x.tutorialPromptSeen==='boolean'?x.tutorialPromptSeen:false,tutorialCompleted:typeof x.tutorialCompleted==='boolean'?x.tutorialCompleted:false,chars}}"
progress_new = "const LEVEL_THRESHOLDS=[0,1,3,6,10];\nfunction defaultDeckBuild(){return{enabled:false,slots:[...CORE_IDS].slice(0,29),variants:{},joker:'J1'}}\nfunction normalizeDeckBuild(x){const base=defaultDeckBuild();if(!x||typeof x!=='object')return base;const slots=[];if(Array.isArray(x.slots))for(const slot of x.slots){if(slots.length>=29)break;if(ALL_REGULAR.includes(slot)&&!slots.includes(slot))slots.push(slot)}const variants={};if(x.variants&&typeof x.variants==='object')for(const[slot,id]of Object.entries(x.variants)){if(ALL_REGULAR.includes(slot)&&NAMED[id]&&id?.[0]!=='J'&&namedSlot(id)===slot)variants[slot]=id}const joker=NAMED[x.joker]&&String(x.joker).startsWith('J')?x.joker:'J1';return{enabled:!!x.enabled,slots,variants,joker}}\nfunction defaultProgress(){return{totalClears:0,selectedChar:'wanderer',selectedTheme:'mixed',tutorialPromptSeen:false,tutorialCompleted:false,deckBuild:defaultDeckBuild(),chars:{wanderer:0,collector:0,salvager:0,jester:0}}}\nfunction normalizeProgress(x){const base=defaultProgress();if(!x||typeof x!=='object')return base;const chars={...base.chars};for(const id of Object.keys(chars)){const n=Number(x.chars?.[id]);if(Number.isFinite(n)&&n>=0)chars[id]=Math.floor(n)}const tc=Number(x.totalClears);return{totalClears:Number.isFinite(tc)&&tc>=0?Math.floor(tc):0,selectedChar:Object.prototype.hasOwnProperty.call(CHARACTERS,x.selectedChar)?x.selectedChar:'wanderer',selectedTheme:Object.prototype.hasOwnProperty.call(THEME_BUILD_PROFILES,x.selectedTheme)?x.selectedTheme:'mixed',tutorialPromptSeen:typeof x.tutorialPromptSeen==='boolean'?x.tutorialPromptSeen:false,tutorialCompleted:typeof x.tutorialCompleted==='boolean'?x.tutorialCompleted:false,deckBuild:normalizeDeckBuild(x.deckBuild),chars}}"
assert progress_old in text, 'progress schema anchor changed'
text = text.replace(progress_old, progress_new, 1)

# Battle deck: custom construction is opt-in and preserves the existing automatic generator as fallback.
make_old = "function makeDeck(owner,charId=progress.selectedChar,themeId=owner==='player'?(progress.selectedTheme||'mixed'):'mixed'){\n const unlocked=[...unlockedNamed()].filter(id=>id[0]!=='J'&&NAMED[id]);"
make_new = "function makeCustomBattleDeck(owner){if(owner!=='player'||!progress.deckBuild?.enabled)return null;const build=normalizeDeckBuild(progress.deckBuild);if(build.slots.length!==29)return null;const open=unlockedNamed(),cards=build.slots.map(slot=>{const chosen=build.variants[slot],variantId=chosen&&open.has(chosen)&&namedSlot(chosen)===slot?chosen:null,{suit,rank}=parseRegularId(slot);return makeCard(suit,rank,!!variantId,owner,variantId)});const jokers=[...open].filter(id=>id[0]==='J'&&NAMED[id]),jid=jokers.includes(build.joker)?build.joker:(jokers.includes('J1')?'J1':jokers[0]);if(jid)cards.push(makeCard('J',jid,true,owner,jid));return cards.length===30?shuffle(cards):null}\nfunction makeDeck(owner,charId=progress.selectedChar,themeId=owner==='player'?(progress.selectedTheme||'mixed'):'mixed'){\n const custom=makeCustomBattleDeck(owner);if(custom)return custom;\n const unlocked=[...unlockedNamed()].filter(id=>id[0]!=='J'&&NAMED[id]);"
assert make_old in text, 'makeDeck anchor changed'
text = text.replace(make_old, make_new, 1)

# Deckbuilder model, analysis, and interactive render.
render_anchor = "function renderProgress(){document.getElementById('totalClears').textContent=progress.totalClears;"
render_helpers = "function deckSlotVariants(slot){const open=unlockedNamed();return[...open].filter(id=>id[0]!=='J'&&NAMED[id]&&namedSlot(id)===slot).sort((a,b)=>(NAMED[a]?.n||a).localeCompare(NAMED[b]?.n||b))}\nfunction effectiveDeckVariant(slot){const id=progress.deckBuild?.variants?.[slot];return id&&unlockedNamed().has(id)&&namedSlot(id)===slot?id:null}\nfunction deckBuildAnalysis(slots=progress.deckBuild?.slots||[]){const suits={S:0,H:0,D:0,C:0},ranks=Object.fromEntries(Object.keys(RANK_VALUE).map(r=>[r,0]));for(const slot of slots){const{suit,rank}=parseRegularId(slot);if(suit in suits)suits[suit]++;if(rank in ranks)ranks[rank]++}const setPairs=Object.values(ranks).filter(n=>n>=2).length,setReady=Object.values(ranks).filter(n=>n>=3).length;let runWindows=0,longestRun=0;for(const suit of['S','H','D','C']){const vals=new Set(slots.filter(x=>x[0]===suit).map(x=>RANK_VALUE[parseRegularId(x).rank]));for(let v=1;v<=11;v++)if(vals.has(v)&&vals.has(v+1)&&vals.has(v+2))runWindows++;let streak=0;for(let v=1;v<=13;v++){streak=vals.has(v)?streak+1:0;longestRun=Math.max(longestRun,streak)}}return{suits,ranks,setPairs,setReady,runWindows,longestRun}}\nfunction renderDeckBuilder(){const grid=document.getElementById('deckSlotGrid');if(!grid)return;if(!progress.deckBuild)progress.deckBuild=defaultDeckBuild();progress.deckBuild=normalizeDeckBuild(progress.deckBuild);const build=progress.deckBuild,selected=new Set(build.slots),analysis=deckBuildAnalysis(build.slots),valid=build.slots.length===29,mode=document.getElementById('deckModeState'),modeBtn=document.getElementById('deckModeBtn'),start=document.getElementById('startWithCharBtn');if(mode){mode.textContent=build.enabled?'커스텀 적용':'자동 구성';mode.classList.toggle('on',build.enabled)}if(modeBtn){modeBtn.textContent=build.enabled?'자동 구성으로 전환':'커스텀 덱 사용';modeBtn.disabled=!build.enabled&&!valid;modeBtn.onclick=()=>{if(!build.enabled&&!valid)return;build.enabled=!build.enabled;saveProgress();renderDeckBuilder();renderStartScreen()}}const rankLine=Object.keys(RANK_VALUE).map(r=>`<span class=\"deckRankChip\">${r} ${analysis.ranks[r]}</span>`).join('');document.getElementById('deckAnalysis').innerHTML=`<div class=\"deckAnalysisBox\">선택 <b>${build.slots.length}/29</b><br>네임드 ${build.slots.filter(s=>effectiveDeckVariant(s)).length} · 순수 ${build.slots.filter(s=>!effectiveDeckVariant(s)).length}</div><div class=\"deckAnalysisBox\">무늬 · ♠ ${analysis.suits.S} / ♥ ${analysis.suits.H}<br>♦ ${analysis.suits.D} / ♣ ${analysis.suits.C}</div><div class=\"deckAnalysisBox\">세트 재료 · 2장+ 숫자 <b>${analysis.setPairs}</b><br>3장+ 숫자 <b>${analysis.setReady}</b></div><div class=\"deckAnalysisBox\">런 재료 · 3연속 창 <b>${analysis.runWindows}</b><br>최장 연속 <b>${analysis.longestRun}</b></div><div class=\"deckRankLine\">${rankLine}</div><div class=\"deckWarn ${valid?'deckOk':''}\">${valid?'구성 완료 · 정규 29 + 조커 1 = 30장.':'커스텀 적용 전 정규 슬롯을 정확히 29개 선택하세요.'}</div>`;grid.innerHTML=ALL_REGULAR.map(slot=>{const{suit,rank}=parseRegularId(slot),on=selected.has(slot),variants=deckSlotVariants(slot),vid=effectiveDeckVariant(slot),label=vid?NAMED[vid].n:'순수',red=suit==='H'||suit==='D'?'red':'';return`<div class=\"deckSlot ${on?'selected':''}\"><button class=\"deckSlotPick ${red}\" data-deck-slot=\"${slot}\" type=\"button\">${rank}${SUIT_SYMBOL[suit]}<small>${on?'포함':'제외'}</small></button><button class=\"deckVariantBtn ${vid?'named':''}\" data-deck-variant=\"${slot}\" type=\"button\" ${!on||!variants.length?'disabled':''} title=\"${variants.length?`변형 ${variants.length}종 순환`:'해금 변형 없음'}\">${label}</button></div>`}).join('');grid.querySelectorAll('[data-deck-slot]').forEach(b=>b.onclick=()=>{const slot=b.dataset.deckSlot,i=build.slots.indexOf(slot);if(i>=0){build.slots.splice(i,1);delete build.variants[slot]}else if(build.slots.length<29)build.slots.push(slot);saveProgress();renderDeckBuilder()});grid.querySelectorAll('[data-deck-variant]').forEach(b=>b.onclick=()=>{const slot=b.dataset.deckVariant,variants=deckSlotVariants(slot),cur=effectiveDeckVariant(slot),options=[null,...variants],i=options.indexOf(cur);const next=options[(i+1)%options.length];if(next)build.variants[slot]=next;else delete build.variants[slot];saveProgress();renderDeckBuilder()});const jokers=[...unlockedNamed()].filter(id=>id[0]==='J'&&NAMED[id]);const jp=document.getElementById('jokerPicker');jp.innerHTML=jokers.map(id=>`<button class=\"pixelBtn ${build.joker===id?'goldBtn':''}\" data-deck-joker=\"${id}\" type=\"button\">${NAMED[id].n}</button>`).join('')||'<span class=\"sub\">조커 없음</span>';jp.querySelectorAll('[data-deck-joker]').forEach(b=>b.onclick=()=>{build.joker=b.dataset.deckJoker;saveProgress();renderDeckBuilder()});document.getElementById('deckResetBtn').onclick=()=>{const enabled=build.enabled;progress.deckBuild={...defaultDeckBuild(),enabled};saveProgress();renderDeckBuilder();renderStartScreen()};if(start){start.disabled=build.enabled&&!valid;start.textContent=build.enabled&&!valid?`커스텀 덱 ${build.slots.length}/29 · 구성 필요`:'선택 캐릭터/테마로 새 게임'}}\n" + render_anchor
assert render_anchor in text, 'renderProgress anchor changed'
text = text.replace(render_anchor, render_helpers, 1)

# Ensure the editor refreshes whenever the progress modal refreshes.
progress_end = "document.getElementById('nextUnlocks').innerHTML=[...chars,...next].join('')||'<span class=\"unlockChip\">현재 프로토타입 해금 완료</span>'}"
progress_end_new = "document.getElementById('nextUnlocks').innerHTML=[...chars,...next].join('')||'<span class=\"unlockChip\">현재 프로토타입 해금 완료</span>';renderDeckBuilder()}"
assert progress_end in text, 'renderProgress end anchor changed'
text = text.replace(progress_end, progress_end_new, 1)

# Start-screen clarity: show when the deterministic custom deck is active.
start_old = "el.textContent=`${ch.name} Lv.${charLevel(progress,id)} · ${theme.displayName} · 전체 ${progress.totalClears}클리어${typeof developerModeActive==='function'&&developerModeActive()?' · DEV':''}`;"
start_new = "el.textContent=`${ch.name} Lv.${charLevel(progress,id)} · ${theme.displayName}${progress.deckBuild?.enabled?' · 커스텀 덱':''} · 전체 ${progress.totalClears}클리어${typeof developerModeActive==='function'&&developerModeActive()?' · DEV':''}`;"
assert start_old in text, 'start meta anchor changed'
text = text.replace(start_old, start_new, 1)

index.write_text(text)

r = road.read_text()
old_a = '- [ ] Player-facing 52-slot deck construction'
new_a = '- [x] Player-facing 52-slot deck construction — progress screen now exposes all 52 canonical rank+suit slots; custom mode selects exactly 29 regular slots plus 1 Joker for the existing 30-card battle deck, with per-slot PURE ↔ unlocked NAMED cycling and legacy automatic generation preserved as an opt-in fallback'
old_b = '- [ ] Rank/suit/SET/RUN distribution analysis UI'
new_b = '- [x] Rank/suit/SET/RUN distribution analysis UI — deckbuilder reports suit counts, all 13 rank counts, 2+/3+ same-rank SET material, 3-card RUN windows, longest same-suit streak, PURE/NAMED split, and invalid 29-slot construction warnings live while editing'
assert old_a in r and old_b in r, 'M11 deckbuilder roadmap anchors changed'
r = r.replace(old_a, new_a, 1).replace(old_b, new_b, 1)
road.write_text(r)
